LINES={'O-001': ['隙（\u3000）からの攻撃時、攻撃+1'], 'O-005': ['【渾身】攻撃の際、攻撃を+1しても良い。その', '場合は、攻撃の後に耐久を1消費する。'], 'O-008': ['【再生】攻撃の際、耐久が1増加する（この処理', 'は相手の反撃の前）'], 'O-009': ['【飲酒】攻撃時、追加で霊力（\u3000）2を消費す', 'るとその際の攻撃+1'], 'T-001': ['【術式】この式神はダメージを与えられない。', '耐久がゼロになった時、盤上の味方1体に耐久+2'], 'T-003': ['味方を攻撃の対象にすることができる。その場', '合、対象にダメージを与えるのではなく、この', '式神の攻撃分、耐久を増加する。'], 'T-006': ['攻撃・反撃によって対象の耐久を0にした場合、', 'その位置に移動する。この時、向きを90度変え', 'られる。'], 'T-008': ['・この式神に「回転」の命令をする際、自身が回転する代わ', 'りに、敵味方を問わず、他の式神を90度回転させることがで', 'きる。', '・この式神の攻撃は隙（\u3000）、反撃間合（\u3000）を無視する。']}
